VStack(alignment: .leading, spacing: 16) {
    HStack(spacing: 4) {
        MonarchButton("Previous page", systemImage: "chevron.left", variant: .ghost, size: .sm, isIconOnly: true) { page = max(1, page - 1) }
        pageButton({{full.items.0}})
        Text({{full.items.1}}).monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
        pageButton({{full.items.2}})
        pageButton({{full.items.3}})
        pageButton({{full.items.4}})
        Text({{full.items.5}}).monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
        pageButton({{full.items.6}})
        MonarchButton("Next page", systemImage: "chevron.right", variant: .ghost, size: .sm, isIconOnly: true) { page += 1 }
    }
    HStack(spacing: 4) {
        Text({{compact.range}}).monarchTextStyle(.bodySmall).monospacedDigit().foregroundStyle(theme.colors.textMuted)
            .padding(.trailing, 8)
        MonarchButton("Previous page", systemImage: "chevron.left", variant: .ghost, size: .sm, isIconOnly: true) { page = max(1, page - 1) }
        MonarchButton("Next page", systemImage: "chevron.right", variant: .ghost, size: .sm, isIconOnly: true) { page += 1 }
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var page = {{page}}

private func pageButton(_ label: String) -> some View {
    let isCurrent = String(page) == label
    return Button { page = Int(label) ?? page } label: {
        Text(label)
            .monarchTextStyle(.label)
            .foregroundStyle(isCurrent ? theme.colors.accentStrong : theme.colors.textMuted)
            .frame(minWidth: 36, minHeight: 36)
            .background(
                isCurrent ? theme.colors.accentSubtle : Color.clear,
                in: RoundedRectangle(cornerRadius: 8, style: .continuous)
            )
            .contentShape(Rectangle())
    }
    .buttonStyle(.plain)
    .accessibilityLabel(label)
    .accessibilityAddTraits(isCurrent ? .isSelected : [])
}

